const LIVE_LINK_CAP = 30;
const NOTE_MIN_CHARS = 10;
const FLUSH_BUDGET = { c: 6000, l: 60, n: 10 };
const OFFLINE_BUDGET = { c: 20000, l: 300, n: 40 };
const SESSION_GAP = 30 * MIN;
