    for (const a of def.alt || []) if (a.when(t, mode)) { rows = a._rows || (a._rows = build(a, base)); break; }
    const w = base[0].length, h = base.length;
    const bh = rows.length;
    const x0 = Math.round(G / 2 - w / 2);
