        rowsAt(this, ['..KRK..', '..KYK..', '.KRGRK.', '.KYYYK.', 'KRRBRRK', 'KWKWKWK'], a.hx - 3, a.top - 6, { K: c.K, R: '#ff5a5a', Y: '#ffd65a', W: '#ffffff', G: '#78c46a', B: '#5aa0ff' }, [1, 1, 1, 0, 0, 0]);
