        if (!a.curled) for (const x of [a.left - 1, a.right + 1]) { this.px(x, a.my + 1, S); this.px(x, a.my + 2, s2); this.px(x, a.my, c.K); }
        if (t % 2.5 < 0.2) this.px(a.hx - 4, a.my + 2, '#ffffff');
