        this.pattern(['.KKKKKKKKKKK.', 'KWWRWRWWRWRWK', 'KRWRWWRWRWWRK', '.KKKKKKKKKKK.'], a.hx - 6, a.top - 1, { K: c.K, R: '#d8303b', W: '#ffffff' });
        this.pattern(['.KK..', 'KRRKK', 'KRRRK', '.KKRK', '...KK'], a.hx + 5, a.top - 1, { K: c.K, R: '#d8303b' });
