        this.pattern(['.KKK.', '.KTK.', '.KTK.', '.KTK.', '.KTK.', 'KKKKK', 'KRRRK', 'KrrrK'], a.hx - 2, a.top - 6, { K: c.K, T: '#c48b56', R: '#d8303b', r: '#9a1a22' });
