        const m = { Y: beat === 0 ? '#fff27a' : '#ffd83a', y: '#ffb01a', W: '#ffffff', K: '#6a3208' };
        const BIG = ['...K...', '..KYK..', 'KKYYYKK', 'KyYWYyK', '.KYYYK.', '.KyKyK.', '.KK.KK.'];
