  const OPEN = new Set(['open', 'wide', 'sparkle', 'teary']);
  const eyeOpen = (g, side) => {
    const k = g.p && g.p.eyes;
    if (k === 'wink') return side < 0;
    return !k || OPEN.has(k);
  };
