          if (p > 0.7) for (const [dx, dy] of [[-2, 0], [a.ew + 1, 1], [0, -2], [1, a.eh + 1]]) this.px(ex + dx, ey + dy, rgba(255, 60, 30, (p - 0.7) * 1.2), false);
