        this.pattern(['...KKKKKKK...', '.KKgWWWWWgKK.', 'KWWWWWWWWWWWK', 'KgWWRRRRRWWgK', 'KWWRKKKKKRWWK', 'KWWRKWWWKRWWK', 'KWWRKKKKKRWWK', 'KgWWRRRRRWWgK', 'KWWWWWWWWWWWK', '.KKgWWWWWgKK.', '..s.KKKKK.s..'], 32, 34, M);
